import type { HelloAdaLanguage } from "./languages";

export type AdminCopy = Record<string, string>;

type AdminLocale = Exclude<HelloAdaLanguage, "en" | "fr" | "ta">;

const section = (prefix: string, copy: AdminCopy): AdminCopy =>
  Object.fromEntries(
    Object.entries(copy).map(([key, value]) => [`${prefix}.${key}`, value]),
  );

const pack = (...sections: AdminCopy[]) => Object.assign({}, ...sections);

